'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => 'mw-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
const localDate = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const localTime = d => localDate(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
const formatDate = (v,opts={weekday:'long',day:'numeric',month:'long'}) => new Date(v).toLocaleDateString('en-GB',opts);
const formatTime = v => new Date(v).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});
let state;try{state=JSON.parse(localStorage.getItem('meanwhile-v1'));}catch{}
state=state||{appointment:localDate(new Date(Date.now()+7*86400000))+'T10:00',duration:60,weekly:true,tasks:[],notes:[],thoughts:[],prep:'',customSections:[]};
const oldState=JSON.parse(JSON.stringify(state));
state.notes=state.notes||[];state.notes.forEach(n=>{n.id=n.id||uid();});
state.thoughts=state.thoughts||[];state.customSections=state.customSections||[];
state.preferences={theme:'light',tone:'Warm and friendly',length:'Concise',emojis:false,instructions:'',summary:'Key themes, practical next steps and questions to bring back.',useProfile:true,...state.preferences};
state.about=state.about||{};state.contexts=state.contexts||{};state.reflections=state.reflections||{};
state.reminders={debrief:true,practice:true,brief:true,private:true,lead:'30',practiceTime:'18:00',practiceDays:['Tue','Thu'],...state.reminders};
state.excludedCategories=state.excludedCategories||[];
let view='home',category='basics',questionSearch='',answerFilter='all',lastFocus=null,saveOK=true;
let capture=null,recordTimer=null,transcriptTimer=null,recordSeconds=0,isRecording=false,isPaused=false,captureGeneration=0;
const responseDefaults={debrief:'We talked about seeking reassurance when I am already fairly sure of my own judgement. I would like to explore how to start a small task without waiting for confirmation that I am doing it correctly.',thought:'I want to bring up how anticipation sometimes stops me taking the first step, even when I know what I want to do.',practice:'I chose one small task and started for two minutes before asking anyone what they thought. I noticed the urge to check, and I want to discuss what that felt like.',prep:'I want to discuss what kind of structure would help me follow through between sessions.',nextstep:'Before next time, I want to think of one small exercise I would choose for myself and discuss it with my therapist.'};
function save(){try{localStorage.setItem('meanwhile-v1',JSON.stringify(state));saveOK=true;}catch{saveOK=false;toast('Could not save on this device','Keep a copy before closing. Browser storage may be full or unavailable.');}document.querySelectorAll('.save-status').forEach(e=>e.textContent=saveOK?'Saved on this device':'Not saved');}
function toast(title,body=''){const el=$('#toast');el.className='notify';el.innerHTML=`<strong>${esc(title)}</strong><p>${esc(body)}</p>`;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.className='hidden',4500);}
function schedule(now=new Date()){
 const seed=new Date(state.appointment);if(!Number.isFinite(seed.getTime()))return {next:null,last:null};
 if(!state.weekly)return seed.getTime()+state.duration*60000>now.getTime()?{next:seed,last:null}:{next:null,last:seed};
 let next=new Date(seed);const weeks=Math.floor((now-seed)/(7*86400000));next.setDate(seed.getDate()+weeks*7);
 while(next.getTime()+state.duration*60000<=now.getTime())next.setDate(next.getDate()+7);
 while(true){const before=new Date(next);before.setDate(before.getDate()-7);if(before.getTime()+state.duration*60000<=now.getTime())break;next=before;}
 const last=new Date(next);last.setDate(last.getDate()-7);return {next,last};
}
function context(key){key=key||currentKey();if(!state.contexts[key])state.contexts[key]={prep:'',agenda:[],tasks:[],sections:[],thoughts:[]};return state.contexts[key];}
function currentKey(){const next=schedule().next;return next?localTime(next):'unscheduled';}
if(!state.schemaVersion){const c=context();c.prep=state.prep||'';c.tasks=(state.tasks||[]).map(t=>({...t,id:uid(),answer:t.answer||''}));c.sections=state.customSections;c.thoughts=state.thoughts.map(t=>({...t,id:t.id||uid()}));state.schemaVersion=2;try{localStorage.setItem('meanwhile-before-v2',JSON.stringify(oldState));}catch{}save();}
function latestSession(){return [...state.notes].sort((a,b)=>new Date(b.date)-new Date(a.date))[0];}
function applyTheme(){const theme=state.preferences.theme;document.body.classList.toggle('dark',theme==='dark'||theme==='system'&&window.matchMedia('(prefers-color-scheme:dark)').matches);document.querySelector('meta[name=theme-color]').content=document.body.classList.contains('dark')?'#201d29':'#f7f2eb';}
window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.preferences.theme==='system')applyTheme();});
function name(){return String(state.about.name?.value||'Nicole').trim();}
function pageHeading(ey,title,sub='',extra=''){return `<div class="top"><div><div class="eyebrow">${ey}</div><h1>${esc(title)}</h1>${sub?`<p class="sub">${sub}</p>`:''}</div>${extra}</div>`;}
function nextHeading(){const next=schedule().next;if(!next)return 'Add your next session';const today=new Date();const days=Math.round((new Date(localDate(next))-new Date(localDate(today)))/86400000);if(next<=today)return 'Your session is now';return days===0?'Today':days===1?'Tomorrow':`In ${days} days`;}
function nextMeta(){const n=schedule().next;return n?`${formatDate(n)} · ${formatTime(n)} · ${state.duration} min`:'Set a date to organise your next-session preparation.';}
function go(v){closeModal();view=v;render();window.scrollTo(0,0);}
function render(){applyTheme();$('#profile-button').textContent=name().slice(0,1).toUpperCase()||'N';$('#profile-button').classList.toggle('active',view==='settings');const nav=[['home','⌂','Dashboard'],['prep','☷','Next session'],['reflections','✧','Reflections'],['about','◎','About me']];$('#nav').innerHTML=nav.map(([v,i,t])=>`<button onclick="go('${v}')" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}><span aria-hidden="true" class="nav-icon">${i}</span>${t}</button>`).join('');const views={home:dashboard,prep:preparation,reflections:reflectionsPage,about:aboutPage,settings:settingsPage};$('#main').innerHTML=(views[view]||dashboard)();}
function nextCard(){return `<div class="card session-hero"><div class="row"><div class="eyebrow">Next therapy session</div><button class="link" onclick="editAppointment()">Edit</button></div><div class="countdown">${nextHeading()}</div><p class="session-meta">${nextMeta()}</p><div class="button-row"><button class="primary" onclick="go('prep')">Open my preparation →</button></div></div>`;}
function dashboard(){const last=latestSession(),c=context();const n=schedule().next;return pageHeading('Meanwhile',`Hello, ${name()}.`,'Your last session. Your next step. A little less to keep in your head.')+`<div class="grid"><section>${nextCard()}<div class="card"><div class="row section-title"><h2>Last session</h2><button class="link" onclick="openDebrief()">＋ Debrief</button></div>${last?`<p class="meta">${formatDate(last.date)}</p><h3 style="margin-top:12px">${esc(last.title)}</h3><p class="sub">${esc(last.takeaway||last.text).slice(0,350)}</p><button class="link" style="margin-top:17px" onclick="showSession('${last.id}')">Read debrief →</button>${last.nextStep?`<div class="summary"><strong>What I chose for next time</strong><p>${esc(last.nextStep)}</p></div>`:`<div class="notice">What do you want to prepare before your next session?<div><button class="link" onclick="nextStepPrompt('${last.id}')">Choose a next step →</button></div></div>`}`:`<p class="sub">Your latest debrief will live here.</p><button class="primary" style="margin-top:20px" onclick="openDebrief()">Debrief a session</button>`}</div></section><aside><div class="card"><div class="eyebrow">Bring to your next session</div><h2 class="compact-title">Your talking points</h2>${c.agenda.length?`<ul>${c.agenda.slice(0,3).map(a=>`<li>${esc(a.text)}</li>`).join('')}</ul>`:'<p class="hint">Add the things you want to remember to say.</p>'}<p class="hint">${c.tasks.filter(t=>!t.done).length} things to prepare · ${c.thoughts.length} captured thoughts</p><button class="link" style="margin-top:16px" onclick="go('prep')">See all preparation →</button></div><div class="card"><h2 class="compact-title">Catch a thought</h2><div class="button-row"><button class="primary" onclick="captureThought()">◉ Record</button><button class="secondary" onclick="captureThought('text')">✎ Write</button></div></div><div class="card small-card"><button class="link" onclick="go('reflections')">✧ Things to think about →</button><p class="hint">Reflections and optional prompts have their own space.</p></div></aside></div><div class="card">${historyHTML(last?.id)}</div>`;}
function historyHTML(exclude){const notes=[...state.notes].sort((a,b)=>new Date(b.date)-new Date(a.date)).filter(n=>n.id!==exclude);const old=Object.entries(state.contexts).filter(([k])=>k!==currentKey());return `<details class="history-details"><summary>Earlier sessions & preparation (${notes.length+old.length})</summary><p class="hint">Previous notes remain here when your next session moves forward.</p><input type="text" aria-label="Search all session notes" placeholder="Search all session notes…" oninput="searchHistory(this.value)"><div id="history-search-results"></div>${notes.map(n=>`<div class="history-item"><p class="meta">${formatDate(n.date)}</p><button class="link" onclick="showSession('${n.id}')">${esc(n.title)}</button></div>`).join('')}${old.map(([k,c])=>`<div class="history-item"><button class="link" onclick="showOldPrep('${esc(k)}')">Preparation · ${k==='unscheduled'?'Unscheduled':formatDate(k)}</button><p class="small">${c.tasks.length} practice items · ${c.agenda.length} talking points</p></div>`).join('')}${!notes.length&&!old.length?'<p class="empty">Earlier sessions will appear here.</p>':''}</details>`;}
function agendaHTML(c,key){return c.agenda.length?c.agenda.map(a=>`<div class="agenda-item"><div>${esc(a.text)}<p class="small">${esc(a.source||'My talking point')}</p></div><button class="delete" aria-label="Remove talking point" onclick="removeAgenda('${a.id}','${key}')">×</button></div>`).join(''):'<p class="hint">What do you want to make sure you say?</p>';}
function taskHTML(c,key){return c.tasks.length?c.tasks.map(t=>`<div class="task ${t.done?'done':''}"><input type="checkbox" aria-label="Mark ${esc(t.title)} complete" ${t.done?'checked':''} onchange="toggleTask('${t.id}','${key}',this.checked)"><div class="task-body"><button onclick="editTask('${t.id}','${key}')"><strong>${esc(t.title)}</strong></button><p>${esc(t.note||'')}</p>${t.answer?`<p class="task-answer">${esc(t.answer).slice(0,180)}${t.answer.length>180?'…':''}</p>`:''}<button class="link" style="margin-top:10px" onclick="answerTask('${t.id}','${key}')">${t.answer?'Continue my answer':'◉ Work on this'}</button></div><button aria-label="Edit practice item" onclick="editTask('${t.id}','${key}')">✎</button></div>`).join(''):'<p class="hint">Choose what you want to prepare or try. It doesn’t need to be an assignment.</p>';}
function preparation(){const key=currentKey(),c=context(key);return pageHeading('Next session','Everything to bring with you.',nextMeta())+`<div class="grid"><section><div class="card brief"><div class="row"><div class="eyebrow">At a glance</div><span class="badge">Your notes</span></div><h2>${nextHeading()}</h2>${c.agenda.length||c.prep||c.tasks.length?`<ul>${c.agenda.slice(0,4).map(a=>`<li>${esc(a.text)}</li>`).join('')}${c.tasks.slice(0,3).map(t=>`<li>${t.done?'Tried':'Prepare'}: ${esc(t.title)}</li>`).join('')}${c.prep?`<li>${esc(c.prep).slice(0,230)}</li>`:''}</ul>`:'<p class="hint">Add talking points, preparation or a thought below. They will be gathered here.</p>'}<button class="link" onclick="editAppointment()">Edit appointment</button></div><div class="card focus-card"><div class="row section-title"><h2>Before next time</h2><button class="link" onclick="editTask(null,'${key}')">＋ Add</button></div><p class="hint">What you chose to prepare, and your answers to it.</p>${taskHTML(c,key)}<button class="voice-small" onclick="captureNextStep('${key}')">◉ Record something to prepare</button></div><div class="card"><div class="row section-title"><h2>Things to bring up</h2><button class="link" onclick="captureAgenda('${key}','text')">＋ Add</button></div>${agendaHTML(c,key)}<button class="voice-small" onclick="captureAgenda('${key}')">◉ Add by voice</button></div><div class="card"><h2>My preparation</h2><textarea class="inline-input" aria-label="My preparation" oninput="setPrep('${key}',this.value)">${esc(c.prep)}</textarea><div class="row"><button class="voice-small" onclick="voicePrep('${key}')">◉ Add by voice</button><span class="save-status"></span></div>${c.sections.map(s=>`<label class="field"><span>${esc(s.title)}</span><textarea oninput="setSection('${key}','${s.id}',this.value)">${esc(s.text)}</textarea><button type="button" class="voice-small" onclick="voiceSection('${key}','${s.id}')">◉ Add by voice</button></label>`).join('')}<button class="link" style="margin-top:18px" onclick="addSection('${key}')">＋ Add my own section</button></div></section><aside><div class="card"><h2>Worth exploring?</h2><p class="hint">Optional demo suggestions. Choose what fits.</p>${suggestions().slice(0,2).map(s=>`<div class="history-item"><p>${esc(s.question)}</p><p class="small">${esc(s.source)}</p><button class="link" onclick="bringSuggestion('${s.id}')">Add to talking points</button></div>`).join('')}</div><div class="card"><h2>Thoughts I caught</h2>${c.thoughts.map(t=>`<div class="history-item"><p class="transcript">${esc(t.text)}</p><span class="small">${formatDate(t.date,{day:'numeric',month:'short'})}</span><div><button class="link" onclick="bringThought('${t.id}','${key}')">Bring this up →</button></div></div>`).join('')||'<p class="hint">Quick thoughts from your week appear here.</p>'}<button class="voice-small" onclick="captureThought()">◉ Catch a thought</button></div></aside></div><div class="card">${historyHTML(latestSession()?.id)}</div>`;}
function setPrep(key,v){context(key).prep=v;save();}function setSection(key,id,v){context(key).sections.find(s=>s.id===id).text=v;save();}
function toggleTask(id,key,done){context(key).tasks.find(t=>t.id===id).done=done;save();render();}
function removeAgenda(id,key){const c=context(key);c.agenda=c.agenda.filter(a=>a.id!==id);save();render();}
function addAgenda(text,source='My talking point',key=currentKey()){const c=context(key);if(!c.agenda.some(a=>a.text===text))c.agenda.push({id:uid(),text,source});save();}
function captureAgenda(key,mode='voice'){openCapture({title:'What do you want to bring up?',mode,sample:responseDefaults.thought,onSave:text=>{addAgenda(text,'My talking point',key);render();}});}
function captureThought(mode='voice'){const key=currentKey();openCapture({title:'Catch a thought.',mode,sample:responseDefaults.thought,onSave:text=>{context(key).thoughts.push({id:uid(),date:new Date().toISOString(),text});save();render();}});}
function bringThought(id,key){const t=context(key).thoughts.find(t=>t.id===id);addAgenda(t.text,'Thought from this week');toast('Added to your next session');}
function voicePrep(key){openCapture({title:'Add to your preparation',sample:responseDefaults.prep,existing:context(key).prep,onSave:text=>{setPrep(key,text);render();}});}
function voiceSection(key,id){const s=context(key).sections.find(s=>s.id===id);openCapture({title:s.title,existing:s.text,sample:responseDefaults.thought,onSave:text=>{s.text=text;save();render();}});}
function editTask(id,key=currentKey()){const t=context(key).tasks.find(t=>t.id===id)||{title:'',note:''};showModal(`<h2>Something to prepare</h2><label class="field"><span>What would you like to try or think about?</span><input id="task-title" type="text" value="${esc(t.title)}"></label><label class="field"><span>Context or instructions</span><textarea id="task-note">${esc(t.note)}</textarea></label><div class="actions">${id?`<button class="secondary" onclick="removeTask('${id}','${key}')">Remove</button>`:''}<button class="primary" onclick="saveTask('${id||''}','${key}')">Save preparation</button></div>`);}
function saveTask(id,key){const title=$('#task-title').value.trim();if(!title){toast('Add something to prepare');return;}const c=context(key),t=c.tasks.find(t=>t.id===id);if(t){t.title=title;t.note=$('#task-note').value;}else c.tasks.push({id:uid(),title,note:$('#task-note').value,done:false,answer:''});save();closeModal();render();}
function removeTask(id,key){context(key).tasks=context(key).tasks.filter(t=>t.id!==id);save();closeModal();render();}
function answerTask(id,key){const t=context(key).tasks.find(t=>t.id===id);openCapture({title:t.title,description:'Your answer stays with this preparation item.',existing:t.answer,sample:responseDefaults.practice,onSave:text=>{t.answer=text;save();render();}});}
function captureNextStep(key){openCapture({title:'What do you want to prepare?',sample:responseDefaults.nextstep,onSave:text=>{context(key).tasks.push({id:uid(),title:text,note:'Chosen for this session',done:false,answer:''});save();render();}});}
function addSection(key){showModal(`<h2>Add a preparation section</h2><label class="field"><span>Section name</span><input id="section-title" type="text" placeholder="Questions, patterns, or something else"></label><div class="actions"><button class="primary" onclick="saveSection('${key}')">Add section</button></div>`);}
function saveSection(key){const title=$('#section-title').value.trim();if(!title)return;context(key).sections.push({id:uid(),title,text:''});save();closeModal();render();}
function answered(a){return a&&(String(a.value??'').trim()!==''||String(a.note??'').trim()!=='');}
function aboutPage(){const total=QUESTIONS.filter(q=>answered(state.about[q.id])).length;return pageHeading('About me','A little more of your story.',`${QUESTIONS.length} optional prompts. Answer one, leave the rest, come back whenever you like.`)+`<div class="notice">This is an editable notebook, not a test. There is no submit button or score. Everything is optional; these are reflection prompts, not a clinical questionnaire.</div><div class="filter-row"><input type="text" aria-label="Search About Me questions" placeholder="Find a question…" value="${esc(questionSearch)}" oninput="questionSearch=this.value;renderQuestions()"><select aria-label="Filter About Me answers" onchange="answerFilter=this.value;renderQuestions()"><option value="all" ${answerFilter==='all'?'selected':''}>All questions</option><option value="answered" ${answerFilter==='answered'?'selected':''}>With an answer</option><option value="unanswered" ${answerFilter==='unanswered'?'selected':''}>Not answered yet</option></select></div><div class="question-layout"><aside class="category-menu">${QUESTION_GROUPS.map(([id,title])=>`<button data-category="${id}" onclick="chooseCategory('${id}')" class="${category===id?'active':''}">${title}<span class="count">${QUESTIONS.filter(q=>q.category===id&&answered(state.about[q.id])).length}</span></button>`).join('')}</aside><section><div class="card"><div class="row"><h2 id="category-title">${QUESTION_GROUPS.find(g=>g[0]===category)[1]}</h2><span class="status" id="about-count">${total} answered</span></div><p class="hint">Your words can change as you do. No need to finish.</p><label class="task"><span class="small" style="flex:1">Include this section when AI is connected and profile context is enabled</span><input type="checkbox" aria-label="Include this About Me section in future AI context" ${!state.excludedCategories.includes(category)?'checked':''} onchange="toggleCategoryContext(this.checked)"></label><div id="question-list">${questionList()}</div></div></section></div>`;}
function questionList(){return QUESTIONS.filter(q=>(questionSearch?q.text.toLowerCase().includes(questionSearch.toLowerCase()):q.category===category)&&(answerFilter==='all'||answerFilter==='answered'&&answered(state.about[q.id])||answerFilter==='unanswered'&&!answered(state.about[q.id]))).map(q=>questionHTML(q)).join('')||'<p class="empty">No matching questions. Try another search or filter.</p>';}
function questionHTML(q){const a=state.about[q.id]||{},value=a.value??'';return `<article class="question" id="question-${q.id}"><div class="q-number">${q.group} · Optional</div><h3><label for="answer-${q.id}">${esc(q.text)}</label></h3>${['text','short','age'].includes(q.type)?`<${q.type==='text'?'textarea':'input'} id="answer-${q.id}" ${q.type!=='text'?`type="${q.type==='age'?'number':'text'}" ${q.type==='age'?'min="0" max="130"':''} value="${esc(value)}"`:''} placeholder="Your answer, whenever you’re ready…" oninput="setAnswer('${q.id}','value',this.value)">${q.type==='text'?esc(value)+'</textarea>':''}`:q.type==='yesno'?`<div class="choices" role="group" aria-label="${esc(q.text)}">${['Yes','No','Sometimes','Not sure'].map(v=>`<button class="choice ${value===v?'selected':''}" aria-pressed="${value===v}" onclick="chooseAnswer('${q.id}','${v}')">${v}</button>`).join('')}</div>`:`<div class="scale" role="group" aria-label="${esc(q.text)}">${Array.from({length:10},(_,i)=>`<button class="${String(value)===String(i+1)?'selected':''}" aria-pressed="${String(value)===String(i+1)}" aria-label="${i+1} out of 10" onclick="chooseAnswer('${q.id}',${i+1})">${i+1}</button>`).join('')}</div><div class="scale-labels"><span>1 · ${q.low}</span><span>10 · ${q.high}</span></div>`}${['yesno','scale'].includes(q.type)?`<details ${a.note?'open':''}><summary>Add context in your own words</summary><textarea aria-label="Context for ${esc(q.text)}" oninput="setAnswer('${q.id}','note',this.value)">${esc(a.note||'')}</textarea></details>`:''}<div class="question-tools"><button class="voice-small" onclick="voiceAnswer('${q.id}')">◉ ${answered(a)?'Add by voice':'Answer by voice'}</button><span class="status" id="status-${q.id}">${a.updated?'Edited '+formatDate(a.updated,{day:'numeric',month:'short'}):'Optional'}</span>${answered(a)?`<button class="tiny-button" onclick="clearAnswer('${q.id}')">Clear</button>`:''}</div></article>`;}
function renderQuestions(){if(!$('#question-list'))return;$('#question-list').innerHTML=questionList();$('#category-title').textContent=questionSearch?'Search results':QUESTION_GROUPS.find(g=>g[0]===category)[1];}
function chooseCategory(id){category=id;questionSearch='';render();}
function toggleCategoryContext(on){state.excludedCategories=state.excludedCategories.filter(x=>x!==category);if(!on)state.excludedCategories.push(category);save();}
function setAnswer(id,field,value){if(id==='age'&&value!==''&&(Number(value)<0||Number(value)>130))return;state.about[id]={...state.about[id],[field]:value,updated:new Date().toISOString()};save();const status=$('#status-'+id);if(status)status.textContent=saveOK?'Saved':'Not saved';const counter=$('#about-count');if(counter)counter.textContent=QUESTIONS.filter(q=>answered(state.about[q.id])).length+' answered';if(id==='name')$('#profile-button').textContent=name().slice(0,1).toUpperCase();}
function chooseAnswer(id,value){setAnswer(id,'value',value);renderQuestions();}
function clearAnswer(id){const previous=state.about[id];delete state.about[id];save();renderQuestions();toast('Answer cleared','Undo is available here.');$('#toast').innerHTML+='<button class="secondary" id="undo-clear">Undo</button>';$('#undo-clear').onclick=()=>{state.about[id]=previous;save();renderQuestions();toast('Answer restored');};}
function voiceAnswer(id){const q=QUESTIONS.find(q=>q.id===id),a=state.about[id]||{},field=['text','short','age'].includes(q.type)?'value':'note';openCapture({title:q.text,description:field==='note'?'Your voice adds context. You can choose a scale or yes/no answer separately.':'Append thoughts to your existing answer, or edit the transcript.',existing:a[field]||'',sample:q.type==='age'?'28':q.id==='name'?'Nicole':q.category==='action'?'I can struggle to start when anticipation makes a task feel bigger than it is. I want to try one small step.':q.category==='selftrust'?'I often look at another person’s reaction to decide whether I am doing the right thing, even when I mostly trust my own view.':'This is something I want to understand better. I would like to bring an example to my next session.',onSave:text=>{if(q.type==='age'&&!/^\d{1,3}$/.test(text.trim())){toast('Use a number for your age','You can edit it in About Me.');return;}setAnswer(id,field,text);renderQuestions();}});}
function profileText(){if(!state.preferences.useProfile)return '';return QUESTIONS.filter(q=>!state.excludedCategories.includes(q.category)&&answered(state.about[q.id])).map(q=>(['text','short'].includes(q.type)?(state.about[q.id].value??''):'')+' '+(state.about[q.id].note??'')).join(' ');}
function suggestions(){const last=latestSession(),recent=(last?.text||'')+' '+(last?.takeaway||''),profile=profileText();const combined=recent+' '+profile;const items=[];const source=last?'Latest debrief · '+formatDate(last.date,{day:'numeric',month:'short'}):'General reflection · no session notes yet';
 if(/reassuran|validat|approval|confirm|judgement/i.test(combined))items.push({id:'selftrust',title:'Whose signal am I waiting for?',question:'When you already have a view, what changes after someone else confirms it? What would help you recognise your own judgement first?',source:source+(/reassuran|validat|approval|confirm|judgement/i.test(profile)?' + About me: self-trust':'')});
 if(/start|anticipat|first step|putting off|procrastinat/i.test(combined))items.push({id:'start',title:'What is the smallest beginning?',question:'Is there a two-minute first step you would choose for yourself before next time? What would you notice before and after trying it?',source:source+(/start|anticipat|first step|putting off|procrastinat/i.test(profile)?' + About me: starting things':'')});
 const patternQ=QUESTIONS.find(q=>q.category==='patterns'&&q.text.startsWith('What pattern do'));const past=state.preferences.useProfile&&!state.excludedCategories.includes('patterns')?state.about[patternQ.id]:null;
 if(answered(past))items.push({id:'pattern',title:'A familiar thread, or something different?',question:`You previously wrote: “${String(past.value||past.note).slice(0,260)}”. Does anything in your latest session feel connected, or is this a different situation?`,source:'About me · your stated pattern'+(last?' + latest debrief':'')});
 if(state.notes.length>1){const old=[...state.notes].sort((a,b)=>new Date(a.date)-new Date(b.date))[0];items.push({id:'earlier',title:'Looking back without assuming a pattern',question:`In “${old.title}”, you wrote: “${String(old.takeaway||old.text).slice(0,220)}”. What feels similar or different now?`,source:'Earlier session · '+formatDate(old.date,{day:'numeric',month:'short',year:'numeric'})});}
 if(!items.length)items.push({id:'useful',title:'What feels worth returning to?',question:'Which part of your last conversation would you like more time with? What makes that part useful to explore?',source});
 items.push({id:'chosen',title:'Structure that belongs to you',question:'What kind of preparation would make your next session more useful? What would make it feel chosen rather than something to get right?',source:'Optional general prompt'});return items;}
function reflectionScope(){return latestSession()?.id||'no-session';}
function reflectionAnswer(id){return state.reflections[reflectionScope()+':'+id]||'';}
function reflectionsPage(){return pageHeading('Reflections','Things to sit with.','Optional questions, separate from what you have chosen to prepare.')+`<div class="notice">Demo suggestions use simple keyword rules and saved excerpts. They are not live AI, assessments or confirmed patterns. You can disagree with every suggestion.</div><div class="grid"><section>${suggestions().map(s=>`<article class="card reflection"><span class="badge">Demo suggestion</span><h2>${esc(s.title)}</h2><p class="sub">${esc(s.question)}</p><span class="source">Based on: ${esc(s.source)}</span><details ${reflectionAnswer(s.id)?'open':''}><summary class="link" style="margin-top:18px;cursor:pointer">${reflectionAnswer(s.id)?'Continue my answer':'Write a response'}</summary><textarea aria-label="Response to ${esc(s.title)}" class="inline-input" oninput="setReflection('${s.id}',this.value)">${esc(reflectionAnswer(s.id))}</textarea></details><div class="button-row"><button class="primary" onclick="voiceReflection('${s.id}')">◉ ${reflectionAnswer(s.id)?'Continue by voice':'Think aloud'}</button><button class="secondary" onclick="bringSuggestion('${s.id}')">Bring to my session</button></div></article>`).join('')}</section><aside><div class="card"><h2>Make it useful.</h2><p class="sub">Keep a thought here, or add it to your talking points. Nothing is assigned automatically.</p><button class="voice-small" onclick="captureThought()">◉ Capture my own thought</button></div><div class="card"><h2>Earlier reflections</h2>${Object.entries(state.reflections).filter(([key,v])=>!key.startsWith(reflectionScope()+':')&&v).map(([key,v])=>`<div class="history-item"><span class="small">${esc(state.notes.find(n=>key.startsWith(n.id+':'))?.title||'Earlier reflection')}</span><p class="transcript">${esc(v)}</p><button class="link" onclick="bringEarlierReflection('${esc(key)}')">Bring to next session</button></div>`).join('')||'<p class="hint">Your previous responses stay here as you add session debriefs.</p>'}</div></aside></div>`;}
function setReflection(id,text){state.reflections[reflectionScope()+':'+id]=text;save();}
function voiceReflection(id){const s=suggestions().find(s=>s.id===id),scope=reflectionScope();openCapture({title:s.question,existing:reflectionAnswer(id),sample:responseDefaults.practice,onSave:text=>{state.reflections[scope+':'+id]=text;save();render();}});}
function bringSuggestion(id){const s=suggestions().find(s=>s.id===id);const answer=reflectionAnswer(id);addAgenda(s.question+(answer?'\nMy response: '+answer:''),'Optional demo suggestion · '+s.source);toast('Added to your talking points','You can review or remove it in Next session.');}
function bringEarlierReflection(key){addAgenda(state.reflections[key],'Earlier reflection');toast('Added to your next session');}
function setPreference(key,value){state.preferences[key]=value;save();if(key==='theme'){applyTheme();render();}if($('#tone-preview'))$('#tone-preview').textContent=tonePreview();}
function tonePreview(){const p=state.preferences;let text=p.tone==='Direct and practical'?'Choose one manageable step before your next session. Record what happened and what you want to discuss.':p.tone==='Curious and gently challenging'?'What would you choose if you did not need someone to confirm it was right? Notice whether you want support, reassurance, or both.':p.tone==='Neutral and clear'?'Your next step is to choose an activity to explore before the next session and note your observations.':'You could choose one small thing to try before next time. There is room to notice what helps and change your mind.';if(p.length==='Detailed')text+=' You might note the situation, your first thought, what you tried and what you would like to explore with your therapist.';return text+(p.emojis?' ✨':'');}
function settingsPage(){const p=state.preferences;return pageHeading('Settings','Make Meanwhile yours.','Appearance, communication preferences and gentle reminders.')+`<div class="settings-grid"><section><div class="card"><h2>Appearance</h2><div class="theme-options" style="margin-top:18px">${['light','dark','system'].map(t=>`<button class="${p.theme===t?'selected':''}" aria-pressed="${p.theme===t}" onclick="setPreference('theme','${t}')">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div></div><div class="card"><h2>How I want AI to communicate</h2><p class="hint">Saved for the integration. The preview below is simulated.</p><label class="field"><span>Tone</span><select onchange="setPreference('tone',this.value)">${['Warm and friendly','Direct and practical','Curious and gently challenging','Neutral and clear'].map(t=>`<option ${p.tone===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span>Response length</span><select onchange="setPreference('length',this.value)">${['Concise','Detailed'].map(t=>`<option ${p.length===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="task"><span style="flex:1">Use emojis</span><input aria-label="Use emojis in AI responses" type="checkbox" ${p.emojis?'checked':''} onchange="setPreference('emojis',this.checked)"></label><label class="field"><span>What should summaries focus on?</span><textarea oninput="setPreference('summary',this.value)">${esc(p.summary)}</textarea><button class="voice-small" onclick="voicePreference('summary')">◉ Add by voice</button></label><label class="field"><span>Anything else about how to speak to me?</span><textarea placeholder="For example: ask one question at a time; challenge assumptions without sounding judgemental." oninput="setPreference('instructions',this.value)">${esc(p.instructions)}</textarea><button class="voice-small" onclick="voicePreference('instructions')">◉ Add by voice</button></label><div class="summary"><span class="badge">Example tone preview</span><p class="ai-preview" id="tone-preview" style="margin-top:10px">${esc(tonePreview())}</p></div><p class="small">Custom instructions and summary focus are saved but cannot be followed by this scripted demo.</p><label class="task"><span style="flex:1"><strong>Use About Me as context</strong><p class="small">Controls local demo prompts and what the future integration may include. Individual sections can be excluded in About Me.</p></span><input aria-label="Use About Me as AI context" type="checkbox" ${p.useProfile?'checked':''} onchange="setPreference('useProfile',this.checked)"></label></div></section><aside><div class="card"><div class="row"><h2>Your profile</h2><button class="link" onclick="go('about')">Edit About Me</button></div><p class="sub">${esc(name())}</p><p class="hint">Your background lives in About Me and can be updated any time.</p></div><div class="card"><h2>Reminder rhythm</h2><p class="hint">Preferences and previews only. Phone notifications are not connected.</p>${reminderRow('debrief','After the session','Prompt a debrief and choose what to prepare.')}${reminderRow('practice','During the week','Return to your chosen practice.')}${reminderRow('brief','Before the next session','Open your preparation and talking points.')}<label class="field"><span>Before therapy</span><select onchange="state.reminders.lead=this.value;save()">${['10','30','60'].map(n=>`<option value="${n}" ${state.reminders.lead===n?'selected':''}>${n} minutes before</option>`).join('')}</select></label><label class="field"><span>During-week reminder time</span><input type="time" value="${state.reminders.practiceTime}" onchange="state.reminders.practiceTime=this.value;save()"></label><div class="choices" role="group" aria-label="Practice reminder days">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<button aria-pressed="${state.reminders.practiceDays.includes(d)}" class="choice ${state.reminders.practiceDays.includes(d)?'selected':''}" onclick="toggleReminderDay('${d}')">${d}</button>`).join('')}</div>${reminderRow('private','Discreet notification text','Hide personal details from the lock-screen preview.')}<div class="button-row"><button class="secondary" onclick="previewNotification('debrief')">After session</button><button class="secondary" onclick="previewNotification('brief')">Before session</button></div><button class="link" style="margin-top:15px" onclick="previewNotification('practice')">Preview during-week reminder</button></div><div class="card"><h2>Your data</h2><p class="hint">Notes stay in this browser. No AI requests are sent. Storage is not encrypted; clearing browser data removes it.</p><button class="link" style="margin-top:15px" onclick="exportData()">Export my notes & preferences</button><p class="save-status" style="margin-top:10px"></p></div></aside></div>`;}
function reminderRow(key,title,sub){return `<label class="task"><span style="flex:1"><strong>${title}</strong><p>${sub}</p></span><input type="checkbox" aria-label="${title}" ${state.reminders[key]?'checked':''} onchange="state.reminders.${key}=this.checked;save()"></label>`;}
function toggleReminderDay(day){const days=state.reminders.practiceDays;state.reminders.practiceDays=days.includes(day)?days.filter(d=>d!==day):[...days,day];save();render();}
function voicePreference(key){openCapture({title:key==='summary'?'What should summaries focus on?':'How would you like AI to speak to you?',existing:state.preferences[key],sample:'Be clear and practical. Ask one question at a time and help me choose a small next step.',onSave:text=>{setPreference(key,text);render();}});}
function previewNotification(kind){const discreet=state.reminders.private,c=context();const title=discreet?'A moment for yourself':kind==='debrief'?'Before it slips your mind':kind==='practice'?'Continue your chosen practice':'Your session is coming up';const text=discreet?'You have some notes to return to.':kind==='debrief'?'Debrief your session, then choose what to prepare before next time.':kind==='practice'?(c.tasks[0]?.title||'What would you like to work on before next time?'):(c.agenda.slice(0,3).map(a=>a.text).join(' • ')||'Your preparation and talking points are ready to open.');showModal(`<div class="eyebrow" style="margin-top:20px">Simulated notification</div><div class="card" style="background:var(--bg);margin-top:18px"><span class="small">❋ Meanwhile · now</span><h3 style="margin-top:12px">${title}</h3><p class="sub">${esc(text)}</p></div><p class="small">This preview does not request permission or schedule an alert.</p><div class="actions"><button class="secondary" onclick="closeModal()">Later</button><button class="primary" onclick="${kind==='debrief'?'openDebrief()':"go('prep')"}">Open ${kind==='debrief'?'debrief':'preparation'}</button></div>`);}
function editAppointment(){showModal(`<h2>Your next appointment</h2><label class="field"><span>Date and time · local device time</span><input type="datetime-local" id="appointment" value="${esc(schedule().next?localTime(schedule().next):state.appointment)}"></label><label class="field"><span>Duration in minutes</span><input type="number" id="duration" min="10" max="240" value="${state.duration}"></label><label><input id="weekly" type="checkbox" ${state.weekly?'checked':''}> Repeat every week</label><p class="hint">Weekly dates move forward automatically. Existing preparation remains available in history.</p><div class="actions"><button class="primary" onclick="saveAppointment()">Save appointment</button></div>`);}
function saveAppointment(){const date=$('#appointment').value,duration=Number($('#duration').value),oldKey=currentKey();if(!date||!Number.isFinite(new Date(date).getTime())||!Number.isFinite(duration)||duration<10||duration>240){toast('Check the date and duration');return;}state.appointment=date;state.duration=duration;state.weekly=$('#weekly').checked;const key=currentKey();if(key!==oldKey&&!state.contexts[key])state.contexts[key]=JSON.parse(JSON.stringify(context(oldKey)));save();closeModal();render();toast('Appointment saved','Your preparation is kept with the updated session. Reminder delivery remains a demo.');}
function showSession(id){const n=state.notes.find(n=>n.id===id);if(!n)return;showModal(`<p class="eyebrow" style="margin-top:20px">${formatDate(n.date)}</p><h2>${esc(n.title)}</h2><div class="summary"><strong>My takeaways</strong><p class="transcript">${esc(n.takeaway||'No separate takeaways added.')}</p></div><h3>Original debrief</h3><p class="transcript sub">${esc(n.text)}</p><div class="summary"><strong>Before next time</strong><p>${esc(n.nextStep||'No preparation chosen yet.')}</p><button class="link" onclick="nextStepPrompt('${id}')">${n.nextStep?'Add another next step':'Choose what to prepare'} →</button></div>`);}
function showOldPrep(key){const c=context(key);showModal(`<h2>Earlier preparation</h2><p class="meta">${key==='unscheduled'?'Unscheduled':formatDate(key)}</p><h3 style="margin-top:20px">What I prepared</h3><p class="transcript sub">${esc(c.prep||'No general preparation.')}</p>${c.tasks.map(t=>`<div class="history-item"><strong>${esc(t.title)}</strong><p class="transcript">${esc(t.answer||'No answer recorded.')}</p></div>`).join('')}<h3 style="margin-top:20px">Talking points & thoughts</h3>${[...c.agenda,...c.thoughts].map(t=>`<p class="transcript sub">${esc(t.text)}</p>`).join('')}${c.sections.map(s=>`<div class="history-item"><strong>${esc(s.title)}</strong><p class="transcript">${esc(s.text)}</p></div>`).join('')}<div class="actions"><button class="secondary" onclick="carryPreparation('${key}')">Carry unfinished items forward</button><button class="primary" onclick="closeModal()">Close</button></div>`);}
function carryPreparation(key){const c=context(key),next=context();let added=0;c.tasks.filter(t=>!t.done).forEach(t=>{if(!next.tasks.some(n=>n.title===t.title)){next.tasks.push({...t,id:uid()});added++;}});save();closeModal();render();toast(`${added} unfinished items carried forward`);}
function showModal(html,label='Meanwhile'){clearRecordTimers();lastFocus=document.activeElement;$('#modal').innerHTML=`<div class="dialog-back"><section class="dialog" role="dialog" aria-modal="true" aria-label="${esc(label)}"><div class="row"><span class="eyebrow" style="margin:0">Meanwhile</span><button class="close" aria-label="Close dialog" onclick="closeModal()">×</button></div>${html}</section></div>`;$('#modal .close').focus();}
function clearRecordTimers(){clearInterval(recordTimer);clearTimeout(transcriptTimer);recordTimer=null;transcriptTimer=null;isRecording=false;isPaused=false;captureGeneration++;}
function closeModal(){clearRecordTimers();$('#modal').innerHTML='';if(lastFocus?.isConnected)lastFocus.focus();}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#modal .dialog')){const els=[...$('#modal .dialog').querySelectorAll('button,input,select,textarea,a,summary')].filter(e=>!e.disabled&&!e.closest('.hidden'));const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function openCapture(options){capture={mode:'voice',existing:'',sample:responseDefaults.thought,...options};capture.text=String(capture.existing||'');captureUI();}
function captureUI(){const c=capture;showModal(`<h2>${esc(c.title)}</h2><p class="modal-sub">${esc(c.description||'Speak first, edit afterwards. This prototype uses a sample transcript.')}</p><div class="tabs"><button class="${c.mode==='voice'?'active':''}" onclick="switchCapture('voice')">◉ Voice</button><button class="${c.mode==='text'?'active':''}" onclick="switchCapture('text')">✎ Write</button></div>${c.mode==='voice'?`<div class="recorder"><span class="pill">Demo · no microphone used</span><div class="wave" aria-hidden="true">│ ı │ ı │ ı │ ı │</div><button class="record" id="record-button" aria-label="Record demo voice note" onclick="startRecord()">●</button><p id="record-status" role="status">Tap to record a three-second demo</p><div class="actions" style="justify-content:center"><button id="pause-button" class="secondary hidden" onclick="pauseRecord()">Pause</button><button id="stop-button" class="secondary hidden" onclick="stopRecord()">Stop & transcribe</button></div></div>`:''}<label class="field"><span>${c.mode==='voice'?'Editable transcript':'Your words'}</span><textarea id="capture-text" oninput="capture.text=this.value" placeholder="Your words…">${esc(c.text)}</textarea></label><p class="small">New demo recordings append to your words. Nothing is sent to an AI service.</p><div class="row"><button class="link" onclick="appendSample()">Insert sample text</button>${c.mode==='voice'?'<button class="link" onclick="playDemo()">▷ Silent playback demo</button>':''}</div><div class="actions"><button class="secondary" onclick="closeModal()">Cancel</button><button id="capture-save" class="primary" onclick="saveCapture()">${esc(c.saveLabel||'Save answer')}</button></div>`,c.title);}
function switchCapture(mode){if(isRecording||transcriptTimer){toast('Finish the recording first');return;}capture.text=$('#capture-text').value;capture.mode=mode;captureUI();}
function appendSample(){if(isRecording||transcriptTimer)return;capture.text=$('#capture-text').value;const separator=capture.text.trim()?'\n\n':'';capture.text+=separator+capture.sample;$('#capture-text').value=capture.text;}
function startRecord(){if(isRecording||transcriptTimer)return;isRecording=true;isPaused=false;recordSeconds=0;$('#record-button').classList.add('live');$('#record-button').disabled=true;$('#pause-button').classList.remove('hidden');$('#stop-button').classList.remove('hidden');$('#capture-save').disabled=true;$('#capture-text').readOnly=true;$('#record-status').textContent='Recording demo · 0:00';recordTimer=setInterval(()=>{if(!isPaused){recordSeconds++;$('#record-status').textContent='Recording demo · 0:'+String(recordSeconds).padStart(2,'0');if(recordSeconds>=3)stopRecord();}},1000);}
function pauseRecord(){isPaused=!isPaused;$('#pause-button').textContent=isPaused?'Resume':'Pause';$('#record-button').classList.toggle('live',!isPaused);$('#record-status').textContent=isPaused?'Paused · your place is kept':'Recording demo · 0:'+String(recordSeconds).padStart(2,'0');}
function stopRecord(){if(!isRecording)return;clearInterval(recordTimer);recordTimer=null;isRecording=false;$('#record-button').classList.remove('live');$('#pause-button').classList.add('hidden');$('#stop-button').classList.add('hidden');$('#record-status').textContent='Creating demo transcript…';const generation=captureGeneration;transcriptTimer=setTimeout(()=>{transcriptTimer=null;if(generation!==captureGeneration||!$('#capture-text'))return;appendSample();$('#record-status').textContent='Demo transcript ready · edit it below';$('#record-button').disabled=false;$('#capture-save').disabled=false;$('#capture-text').readOnly=false;},650);}
function playDemo(){toast('Silent demo playback','This is a UX preview; no audio has been recorded.');}
function saveCapture(){if(isRecording||transcriptTimer){toast('Finish recording first');return;}const text=$('#capture-text').value.trim();if(!text){toast('Add a few words or try the sample');return;}const callback=capture.onSave;closeModal();callback(text);}
let debriefDraft=null;
function openDebrief(){openCapture({title:'What stayed with you?',description:'Start with what you talked about. Next, choose what to prepare before your next session.',sample:responseDefaults.debrief,saveLabel:'Continue to next steps →',onSave:text=>{debriefDraft={text,title:'My session debrief',takeaway:text,date:localDate(schedule().last||new Date()),nextStep:''};debriefReview();}});}
function debriefReview(){const d=debriefDraft;showModal(`<div class="flow-steps"><span>1 · Debrief</span><span class="current">2 · Before next time</span></div><h2>What do you want to prepare?</h2><p class="modal-sub">This is the main next step. Choose something to bring, think about or try — or leave it for later.</p><div class="card focus-card" style="margin-top:20px"><label class="field" style="margin-top:0"><span>Before my next session, I want to…</span><textarea id="debrief-step" placeholder="What did you agree to prepare, or what would you choose for yourself?" oninput="debriefDraft.nextStep=this.value">${esc(d.nextStep)}</textarea></label><button class="primary" onclick="voiceDebriefStep()">◉ Say what I want to prepare</button></div><details><summary class="link" style="cursor:pointer">Review session details & takeaways</summary><label class="field"><span>Session date</span><input type="date" id="debrief-date" value="${esc(d.date)}" onchange="debriefDraft.date=this.value"></label><label class="field"><span>Title</span><input type="text" id="debrief-title" value="${esc(d.title)}" oninput="debriefDraft.title=this.value"></label><label class="field"><span>My takeaways · editable</span><textarea oninput="debriefDraft.takeaway=this.value">${esc(d.takeaway)}</textarea></label><p class="small">Your original debrief is kept separately. No AI summary has been generated.</p><button class="voice-small" onclick="voiceDebriefTakeaway()">◉ Add to takeaways by voice</button></details><div class="actions"><button class="secondary" onclick="saveDebrief(true)">Save & choose later</button><button class="primary" onclick="saveDebrief(false)">Save session & next step</button></div>`,'Choose next-session preparation');}
function voiceDebriefStep(){debriefDraft.nextStep=$('#debrief-step').value;openCapture({title:'What do you want to prepare before next time?',existing:debriefDraft.nextStep,sample:responseDefaults.nextstep,onSave:text=>{debriefDraft.nextStep=text;debriefReview();}});}
function voiceDebriefTakeaway(){openCapture({title:'My takeaways',existing:debriefDraft.takeaway,sample:responseDefaults.thought,onSave:text=>{debriefDraft.takeaway=text;debriefReview();}});}
function saveDebrief(later){debriefDraft.nextStep=$('#debrief-step').value.trim();if(!later&&!debriefDraft.nextStep){toast('Choose a next step, or save for later');return;}if(!debriefDraft.date||!Number.isFinite(new Date(debriefDraft.date).getTime())){toast('Choose a valid session date');return;}const d={...debriefDraft,id:uid(),date:debriefDraft.date+'T12:00:00',kind:'Session debrief',prepKey:currentKey()};state.notes.unshift(d);if(d.nextStep)context(d.prepKey).tasks.push({id:uid(),title:d.nextStep,note:'Chosen after '+formatDate(d.date,{day:'numeric',month:'short'}),done:false,answer:'',sessionId:d.id});save();closeModal();view='home';render();toast(saveOK?'Session saved':'Save unavailable',d.nextStep?'Your chosen preparation is in Next session.':'A prompt to choose your preparation stays on the dashboard.');}
function nextStepPrompt(sessionId){const n=state.notes.find(n=>n.id===sessionId),key=currentKey();openCapture({title:'What do you want to prepare before next time?',sample:responseDefaults.nextstep,onSave:text=>{n.nextStep=n.nextStep?n.nextStep+'\n'+text:text;n.prepKey=key;context(key).tasks.push({id:uid(),title:text,note:'Chosen after '+formatDate(n.date,{day:'numeric',month:'short'}),done:false,answer:'',sessionId:n.id});save();render();}});}
function exportData(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download='meanwhile-notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
// A future backend can use this explicit context boundary. No network request is made here.
function buildAIContext(){return {preferences:{...state.preferences},profile:state.preferences.useProfile?QUESTIONS.filter(q=>!state.excludedCategories.includes(q.category)&&answered(state.about[q.id])).map(q=>({id:q.id,question:q.text,...state.about[q.id]})):[],sessions:state.notes.map(n=>({...n})),preparation:JSON.parse(JSON.stringify(state.contexts)),reflections:{...state.reflections}};}
window.Meanwhile={buildAIContext};
applyTheme();render();save();
let activeContext=currentKey();setInterval(()=>{const key=currentKey();if(key!==activeContext){activeContext=key;if(!$('#modal .dialog')&&['home','prep'].includes(view))render();}else if(!$('#modal .dialog')&&view==='home')render();},60000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!$('#modal .dialog'))render();});
if('serviceWorker' in navigator)window.addEventListener('load',()=>{navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline setup unavailable','You can still use Meanwhile online.'));});

function searchHistory(query){const results=$('#history-search-results');if(!query.trim()){results.innerHTML='';return;}const matches=state.notes.filter(n=>(n.title+' '+n.text+' '+(n.takeaway||'')+' '+(n.nextStep||'')).toLowerCase().includes(query.toLowerCase()));results.innerHTML=matches.map(n=>`<div class="history-item"><button class="link" onclick="showSession('${n.id}')">${esc(n.title)}</button><p class="meta">${formatDate(n.date)}</p></div>`).join('')||'<p class="hint">No matching session notes.</p>';}
